
import json
import os
import requests
from pathlib import Path
from dotenv import load_dotenv

API_URL = "https://tokentrail-api.onrender.com"

BACKEND_DIR = Path(__file__).resolve().parent.parent
load_dotenv(BACKEND_DIR / ".env")

PREDICTIONS_FILE = (
    BACKEND_DIR / "data" / "unclassified_nlp_predictions.json"
)

BATCH_SIZE = 500


def main():

    # 1. Load predictions generated by our NLP pipeline
    if not PREDICTIONS_FILE.exists():
        print("Predictions file not found:", PREDICTIONS_FILE)
        return

    predictions = json.loads(
        PREDICTIONS_FILE.read_text(encoding="utf-8")
    )

    print("Total predictions loaded:", len(predictions))

    # 2. Read the API key
    api_key = os.getenv("INGEST_API_KEY", "").strip()

    if not api_key:
        print("INGEST_API_KEY not found in backend/.env")
        return

    headers = {"X-API-Key": api_key}

    # 3. Fetch actual category IDs from backend
    response = requests.get(
        f"{API_URL}/categories",
        timeout=60
    )
    response.raise_for_status()

    categories = response.json()

    category_map = {
        category["name"].strip().lower(): category["id"]
        for category in categories
    }

    print("Backend categories loaded:", len(category_map))

    # 4. Prepare valid classification records
    results = []
    skipped_empty = 0
    skipped_placeholder = 0
    seen_ids = set()

    for prediction in predictions:

        article_id = prediction.get("article_id")
        title = (prediction.get("title") or "").strip()

        # Skip placeholder articles
        if title.lower() in {"string", "null", "none"}:
            skipped_placeholder += 1
            continue

        predicted_categories = prediction.get("categories", [])

        # Never send an empty categories array
        if not predicted_categories:
            skipped_empty += 1
            continue

        if article_id is None:
            continue

        if article_id in seen_ids:
            print("Duplicate article skipped:", article_id)
            continue

        category_scores = []

        for item in predicted_categories:

            category_name = item["category"].strip().lower()

            if category_name not in category_map:
                raise ValueError(
                    f"Unknown category: {item['category']}"
                )

            confidence = float(item["confidence"])

            if not 0 <= confidence <= 1:
                raise ValueError(
                    f"Invalid confidence for article {article_id}"
                )

            category_scores.append({
                "category_id": category_map[category_name],
                "confidence": confidence
            })

        if category_scores:
            results.append({
                "article_id": article_id,
                "categories": category_scores
            })
            seen_ids.add(article_id)

    # 5. Display upload preview
    print("\n========== UPLOAD PREVIEW ==========")
    print("Total predictions:", len(predictions))
    print("Eligible articles:", len(results))
    print("Skipped without categories:", skipped_empty)
    print("Skipped placeholder articles:", skipped_placeholder)

    print("\nFirst 5 records:")
    print(json.dumps(results[:5], indent=2))

    if not results:
        print("No valid classifications available.")
        return

    total_batches = (
        len(results) + BATCH_SIZE - 1
    ) // BATCH_SIZE

    print("\nBatch size:", BATCH_SIZE)
    print("Total batches:", total_batches)

    # 6. Confirm before modifying live database
    confirm = input(
        "\nType UPLOAD to upload these classifications: "
    )

    if confirm != "UPLOAD":
        print("Upload cancelled. No changes made.")
        return

    # 7. Upload in batches
    total_received = 0
    total_updated = 0
    total_failed = 0

    for batch_number, start in enumerate(
        range(0, len(results), BATCH_SIZE),
        start=1
    ):

        batch = results[start:start + BATCH_SIZE]

        print(
            f"\nUploading batch {batch_number}/{total_batches} "
            f"({len(batch)} articles)..."
        )

        upload_response = requests.post(
            f"{API_URL}/articles/classify/bulk",
            headers=headers,
            json={"results": batch},
            timeout=120
        )

        print("HTTP Status:", upload_response.status_code)

        upload_response.raise_for_status()

        data = upload_response.json()

        print(json.dumps(data, indent=2))

        total_received += data.get("received", 0)
        total_updated += data.get("updated", 0)
        total_failed += data.get("failed", 0)

        if data.get("failed", 0) > 0:
            print("Some records failed. Stopping further batches.")
            break

    # 8. Final report
    print("\n========== UPLOAD COMPLETE ==========")
    print("Total received:", total_received)
    print("Total updated:", total_updated)
    print("Total failed:", total_failed)


if __name__ == "__main__":
    main()
